// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock) public {
        vm.assume(caller != address(0));

        uint256 b = bound(targetBlock, 1, 1_000_000);

        vm.warp(1 days);

        vm.deal(caller, 20 ether);

        vm.roll(b);

        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}('');
        ok = success;

        if (ok) {
            bool drained = address(c).balance == 0;
            bool shouldDrain = (block.number % 15 == 0);
            assertTrue(drained == shouldDrain);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
